from typing import List

def articulationPoints(V: int, adj: List[List[int]]) -> List[int]:
    def dfs(u, parent, visited, disc, low, time, ap):
        nonlocal children
        visited[u] = True
        disc[u] = low[u] = time
        time += 1
        for v in adj[u]:
            if not visited[v]:
                children += 1
                parent[v] = u
                dfs(v, u, visited, disc, low, time, ap)
                low[u] = min(low[u], low[v])
                if parent[u] == -1 and children > 1:
                    ap.add(u)
                elif parent[u] != -1 and low[v] >= disc[u]:
                    ap.add(u)
            elif v != parent[u]:
                low[u] = min(low[u], disc[v])

    visited = [False] * V
    disc = [float('inf')] * V
    low = [float('inf')] * V
    parent = [-1] * V
    ap = set()
    time = 0

    for i in range(V):
        if not visited[i]:
            children = 0
            dfs(i, -1, visited, disc, low, time, ap)

    return sorted(ap) if ap else [-1]
